create table if not exists public.agent_sessions (id text primary key, account text not null check (account in ('Claude normal','Claude Gateway')), status text not null default 'offline' check (status in ('working','paused','finished','offline')), task text not null default '', next_step text not null default '', files jsonb not null default '[]'::jsonb, updated_at timestamptz not null default now());
create table if not exists public.activity_events (id bigint generated by default as identity primary key, account text not null, message text not null, created_at timestamptz not null default now());
alter table public.agent_sessions enable row level security;
alter table public.activity_events enable row level security;
create policy "authenticated can read sessions" on public.agent_sessions for select to authenticated using (true);
create policy "authenticated can insert sessions" on public.agent_sessions for insert to authenticated with check (true);
create policy "authenticated can update sessions" on public.agent_sessions for update to authenticated using (true) with check (true);
create policy "authenticated can read events" on public.activity_events for select to authenticated using (true);
create policy "authenticated can insert events" on public.activity_events for insert to authenticated with check (true);
alter publication supabase_realtime add table public.agent_sessions;
alter publication supabase_realtime add table public.activity_events;
